UOTES,'UTF-8') ?></a><span><?= htmlspecialchars($contact['phone']?:'—',ENT_QUOTES,'UTF-8') ?></span></article><?php endforeach; ?></div></div><div class="detail-pane" data-detail-pane="notifications"><div class="contact-list"><?php foreach($client['recipients'] as $recipient): ?><article><span class="mini-contact-avatar"><i data-lucide="bell"></i></span><div><h3><?= htmlspecialchars($recipient['full_name'],ENT_QUOTES,'UTF-8') ?></h3><p><?= htmlspecialchars($recipient['email']?:$recipient['phone'],ENT_QUOTES,'UTF-8') ?></p></div><span><?= $recipient['notify_email']?'E-mail ':'' ?><?= $recipient['notify_sms']?'· SMS':'' ?></span></article><?php endforeach; ?></div></div><div class="detail-pane" data-detail-pane="history"><ol class="history-timeline"><?php foreach($client['history'] as $event): ?><li><span><i data-lucide="<?= $event['action']==='created'?'plus':($event['action']==='archived'?'archive':'pencil') ?>"></i></span><div><strong><?= htmlspecialchars($event['description'],ENT_QUOTES,'UTF-8') ?></strong><p><?= htmlspecialchars($event['user_name']?:'Système',ENT_QUOTES,'UTF-8') ?> · <?= date('d/m/Y à H:i',strtotime($event['created_at'])) ?></p></div></li><?php endforeach; ?></ol></div></section>
